import math
from fractions import Fraction

def whole_log(b, x):
    # climb or descend through the powers of b: "exactly y" or "between y and y + 1"
    y, p = 0, Fraction(1)
    while p * b <= x:
        p, y = p * b, y + 1
    while p > x:
        p, y = p / b, y - 1
    if p == x:
        return f"exactly {y}"
    return f"between {y} and {y + 1}"

def solve(kind, nums):
    if kind == "exp":
        A, b, x = nums[0], nums[1], nums[2]
        print(f"  {b}^({x}) = {Fraction(b) ** x}, times {A}: {A * Fraction(b) ** x}")
    elif kind == "log":
        b, x = nums[0], Fraction(nums[1], nums[2])
        if x <= 0:
            print(f"  every power of {b} is positive, so log_{b} of {x} is undefined")
        else:
            print(f"  which power of {b} makes {x}? {whole_log(b, x)}")
    elif kind == "sumlog":
        b, x, y = nums[0], nums[1], nums[2]
        print(f"  the product rule: log_{b} {x} + log_{b} {y} = log_{b} {x * y}")
        print(f"  log_{b} {x * y} is {whole_log(b, Fraction(x * y))}")
    elif kind == "changebase":
        b, x = nums[0], nums[1]
        print(f"  ln {x} / ln {b} = {math.log(x):.4f} / {math.log(b):.4f} = {math.log(x) / math.log(b):.4f}")
    elif kind == "solve":
        b, c = nums[0], nums[1]
        if c <= 0:
            print(f"  {b}^x is always positive, so it never equals {c}: no solution")
        else:
            print(f"  ln of both sides: x ln {b} = ln {c}, so x = {math.log(c) / math.log(b):.4f}")
    elif kind == "domain":
        a, c = nums[0], nums[1]
        edge = Fraction(-c, a)
        print(f"  {a}x + ({c}) > 0, and it's 0 at x = {edge}, the asymptote")
        if a > 0:
            print(f"  a > 0: dividing keeps the sign, so x > {edge}")
        else:
            print(f"  a < 0: dividing flips the sign, so x < {edge}")

problems = [
    ("Example 1 · 3 * 2^x at x = -2", "exp", [3, 2, -2]),
    ("Example 2 · log_3 81", "log", [3, 81, 1]),
    ("Example 3 · log 0.01", "log", [10, 1, 100]),
    ("Example 5 · the domain of ln(2x - 6)", "domain", [2, -6]),
    ("Example 7 · log_6 4 + log_6 9", "sumlog", [6, 4, 9]),
    ("Example 10 · log_5 30", "changebase", [5, 30]),
    ("Example 11 · 2^x = 12", "solve", [2, 12]),
    ("Not a whole number: log_2 100", "log", [2, 100, 1]),
    ("No solution: 2^x = -4", "solve", [2, -4]),
    ("A negative coefficient: log(10 - 2x)", "domain", [-2, 10]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

