import math
from fractions import Fraction

def whole_log(b, x):
    # climb or descend through the powers of b: "exactly y" or "between y and y + 1"
    y, p = 0, Fraction(1)
    while p * b <= x:
        p, y = p * b, y + 1
    while p > x:
        p, y = p / b, y - 1
    if p == x:
        return f"exactly {y}"
    return f"between {y} and {y + 1}"

def solve(kind, nums):
    if kind == "exp":
        A, b, x = nums[0], nums[1], nums[2]
        return f"exp: {A} * {b}^({x}) = {A * Fraction(b) ** x}"
    if kind == "log":
        b, x = nums[0], Fraction(nums[1], nums[2])
        if x <= 0:
            return f"log: log_{b} of {x}: undefined"
        return f"log: log_{b} of {x}: {whole_log(b, x)}"
    if kind == "sumlog":
        b, xy = nums[0], nums[1] * nums[2]
        return f"sumlog: log_{b} of {xy}: {whole_log(b, Fraction(xy))}"
    if kind == "changebase":
        b, x = nums[0], nums[1]
        return f"changebase: log_{b} of {x} = {math.log(x) / math.log(b):.4f}"
    if kind == "solve":
        b, c = nums[0], nums[1]
        if c <= 0:
            return "solve: no solution"
        return f"solve: x = {math.log(c) / math.log(b):.4f}"
    a, c = nums[0], nums[1]
    if a > 0:
        return f"domain: x > {Fraction(-c, a)}"
    return f"domain: x < {Fraction(-c, a)}"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

import math

def solve(kind, nums):
    if kind == "isolate":
        a, b, d, c = nums[0], nums[1], nums[2], nums[3]
        r = (c - d) / a
        if r <= 0:
            return "isolate: no solution"
        return f"isolate: x = {math.log(r) / math.log(b):.4f}"
    if kind == "linexp":
        b, m, k, c = nums[0], nums[1], nums[2], nums[3]
        return f"linexp: x = {(math.log(c) / math.log(b) - k) / m:.4f}"
    if kind == "twobases":
        a, b, k = nums[0], nums[1], nums[2]
        return f"twobases: x = {k * math.log(b) / (math.log(a) - math.log(b)):.4f}"
    if kind == "logsum":
        b, p, q, c = nums[0], nums[1], nums[2], nums[3]
        B, C = p + q, p * q - b ** c
        D = B * B - 4 * C
        words = []
        for x in [(-B - math.sqrt(D)) / 2, (-B + math.sqrt(D)) / 2]:
            if x + p > 0 and x + q > 0:
                words.append(f" x = {x:.4f} valid")
            else:
                words.append(f" x = {x:.4f} extraneous")
        return "logsum:" + ",".join(words)
    b, m = nums[0], nums[1]
    return f"digits: {b}^{m} has {int(m * math.log10(b)) + 1} digits"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

