import math
from fractions import Fraction

def signed(n):
    # the text " + n" or " - |n|", for a term written after another
    if n < 0:
        return f" - {-n}"
    return f" + {n}"

def solve(kind, nums):
    if kind == "quadexp":
        b, p, q = nums[0], nums[1], nums[2]
        D, name = p * p - 4 * q, "e" if b == math.e else f"{b}"
        print(f"  u = {name}^x: u^2 + ({p})u + ({q}) = 0, D = {D}")
        if D < 0:
            print("  no real u, so no solution")
        else:
            for u in [(-p - math.sqrt(D)) / 2, (-p + math.sqrt(D)) / 2]:
                if u > 0:
                    print(f"  {name}^x = {u:g}: x = ln {u:g} / ln {name} = {math.log(u) / math.log(b):.4f}")
                else:
                    print(f"  {name}^x = {u:g}: impossible, a power of {name} is positive")
    elif kind == "logquot":
        b, p, q, c = nums[0], nums[1], nums[2], nums[3]
        K = Fraction(b) ** c
        x = (K * q - p) / (1 - K)
        print(f"  (x{signed(p)})/(x{signed(q)}) = {b}^{c} = {K}, so x{signed(p)} = {K}(x{signed(q)}) and x = {x}")
        if x + p > 0 and x + q > 0:
            print(f"  inputs {x + p} and {x + q} are positive: valid")
        else:
            print(f"  inputs {x + p} and {x + q}: not both positive, extraneous")
    elif kind == "compare":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        print(f"  {b} log {a} = {b * math.log10(a):.6f} and {d} log {c} = {d * math.log10(c):.6f}")
        print(f"  exactly, {a}^{b} > {c}^{d} is {a ** b > c ** d}, and {a}^{b} = {c}^{d} is {a ** b == c ** d}")
    elif kind == "fit":
        x1, y1, x2, y2, x3 = nums[0], nums[1], nums[2], nums[3], nums[4]
        b = (y2 / y1) ** (1 / (x2 - x1))
        A = y1 / b ** x1
        print(f"  b = ({y2}/{y1})^(1/{x2 - x1}) = {b:.6f}, A = {y1}/b^{x1} = {A:.6f}")
        print(f"  y({x3}) = {A * b ** x3:.2f}, while the straight line says {y2 + (y2 - y1) / (x2 - x1) * (x3 - x2):.2f}")

problems = [
    ("Example 1 · e^(2x) - 5e^x + 6 = 0", "quadexp", [math.e, -5, 6]),
    ("Example 2 · 4^x - 2^x - 12 = 0", "quadexp", [2, -1, -12]),
    ("Example 3 · log2(x + 7) - log2(x - 1) = 2", "logquot", [2, 7, -1, 2]),
    ("Example 6 · 2^100 against 3^63", "compare", [2, 100, 3, 63]),
    ("Example 7 · through (1, 6) and (4, 48), at x = 7", "fit", [1, 6, 4, 48, 7]),
    ("No real u: 2^(2x) + 2^x + 1 = 0", "quadexp", [2, 1, 1]),
    ("An extraneous answer: log(x + 1) - log(x + 4) = 1", "logquot", [10, 1, 4, 1]),
    ("Equal powers: 8^2 against 4^3", "compare", [8, 2, 4, 3]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

