import math
from fractions import Fraction

def solve(kind, nums):
    if kind == "quadexp":
        b, p, q = nums[0], nums[1], nums[2]
        D = p * p - 4 * q
        words = []
        if D >= 0:
            for u in [(-p - math.sqrt(D)) / 2, (-p + math.sqrt(D)) / 2]:
                if u > 0:
                    words.append(f" x = {math.log(u) / math.log(b):.4f}")
        if words == []:
            return "quadexp: no solution"
        return "quadexp:" + ",".join(words)
    if kind == "logquot":
        b, p, q, c = nums[0], nums[1], nums[2], nums[3]
        K = Fraction(b) ** c
        x = (K * q - p) / (1 - K)
        if x + p > 0 and x + q > 0:
            return f"logquot: x = {x} valid"
        return f"logquot: x = {x} extraneous"
    if kind == "compare":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        if a ** b > c ** d:
            return f"compare: {a}^{b} > {c}^{d}"
        if a ** b < c ** d:
            return f"compare: {a}^{b} < {c}^{d}"
        return f"compare: {a}^{b} = {c}^{d}"
    x1, y1, x2, y2, x3 = nums[0], nums[1], nums[2], nums[3], nums[4]
    b = (y2 / y1) ** (1 / (x2 - x1))
    A = y1 / b ** x1
    return f"fit: b = {b:.4f}, A = {A:.4f}, y({x3}) = {A * b ** x3:.2f}"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))
